import jinja2

@pytest.fixture
def jinja_env():
    env = jinja2.Environment(enable_async=True)
    env.filters['add_two'] = lambda x, y: [i + y for i in x]
    return env

def test_add_two_filter_with_async():
    template = '{% for item in (a.b | add_two(5))[:1] %}{{ item }}{% endfor %}'
    a = {'b': [1, 2, 3]}
    with pytest.raises(TypeError, match="'coroutine' object is not subscriptable"):
        jinja_env().from_string(template).render(a=a)"}}
